/// The palette Ely holds and Sirio's own tokens, for one base colour and appearance.
pub(crate) fn preset(base: BaseColor, appearance: Appearance) -> (Palette, SirioColors) {
    let s = match appearance {
        Appearance::Dark => &SEMANTIC_DARK,
        Appearance::Light => &SEMANTIC_LIGHT,
    };
    let l = match (base, appearance) {
        (BaseColor::Neutral, Appearance::Dark) => &LADDER_NEUTRAL_DARK,
        (BaseColor::Neutral, Appearance::Light) => &LADDER_NEUTRAL_LIGHT,
        (BaseColor::Stone, Appearance::Dark) => &LADDER_STONE_DARK,
        (BaseColor::Stone, Appearance::Light) => &LADDER_STONE_LIGHT,
        (BaseColor::Zinc, Appearance::Dark) => &LADDER_ZINC_DARK,
        (BaseColor::Zinc, Appearance::Light) => &LADDER_ZINC_LIGHT,
        (BaseColor::Gray, Appearance::Dark) => &LADDER_GRAY_DARK,
        (BaseColor::Gray, Appearance::Light) => &LADDER_GRAY_LIGHT,
        (BaseColor::Slate, Appearance::Dark) => &LADDER_SLATE_DARK,
        (BaseColor::Slate, Appearance::Light) => &LADDER_SLATE_LIGHT,
        (BaseColor::Notte, Appearance::Dark) => &LADDER_NOTTE_DARK,
        (BaseColor::Notte, Appearance::Light) => &LADDER_NOTTE_LIGHT,
        (BaseColor::Onice, Appearance::Dark) => &LADDER_ONICE_DARK,
        (BaseColor::Onice, Appearance::Light) => &LADDER_ONICE_LIGHT,
    };
    let palette = Palette {
        bg: l.ely_bg,
        surface: l.ely_surface,
        sunken: l.ely_sunken,
        overlay: l.ely_overlay,
        hover: l.ely_hover,
        active: s.ely_active,
        border: s.ely_border,
        border_strong: s.ely_border_strong,
        fg: l.ely_fg,
        fg_muted: l.ely_fg_muted,
        fg_subtle: l.ely_fg_subtle,
        fg_disabled: l.ely_fg_disabled,
        accent: l.ely_accent,
        accent_hover: l.ely_accent_hover,
        on_accent: l.ely_on_accent,
        on_media: s.ely_on_media,
        focus: l.ely_focus,
        link: l.ely_link,
        selection: s.ely_selection,
        success: s.ely_success,
        warning: s.ely_warning,
        danger: s.ely_danger,
        info: s.ely_info,
        success_subtle: s.ely_success_subtle,
        warning_subtle: s.ely_warning_subtle,
        danger_subtle: s.ely_danger_subtle,
        info_subtle: s.ely_info_subtle,
        backdrop: l.ely_backdrop,
        media_backdrop: s.ely_media_backdrop,
        shimmer: s.ely_shimmer,
        glass: s.ely_glass,
        shadow: s.ely_shadow,
        tooltip_bg: l.ely_tooltip_bg,
        tooltip_fg: l.ely_tooltip_fg,
        paper: s.ely_paper,
        ink: s.ely_ink,
        chart: [s.ely_chart_0, s.ely_chart_1, s.ely_chart_2, s.ely_chart_3, s.ely_chart_4, s.ely_chart_5, s.ely_chart_6, s.ely_chart_7],
        ansi: [s.ely_ansi_0, s.ely_ansi_1, s.ely_ansi_2, s.ely_ansi_3, s.ely_ansi_4, s.ely_ansi_5, s.ely_ansi_6, s.ely_ansi_7, s.ely_ansi_8, s.ely_ansi_9, s.ely_ansi_10, s.ely_ansi_11, s.ely_ansi_12, s.ely_ansi_13, s.ely_ansi_14, s.ely_ansi_15],
        syntax: Syntax {
            keyword: s.ely_syntax_keyword,
            string: s.ely_syntax_string,
            number: s.ely_syntax_number,
            comment: s.ely_syntax_comment,
            function: s.ely_syntax_function,
            type_name: s.ely_syntax_type_name,
            constant: s.ely_syntax_constant,
            property: s.ely_syntax_property,
            tag: s.ely_syntax_tag,
            attribute: s.ely_syntax_attribute,
            operator: s.ely_syntax_operator,
            punctuation: s.ely_syntax_punctuation,
            variable: s.ely_syntax_variable,
        },
    };
    let sirio = SirioColors {
        canvas: l.sirio_canvas,
        frame_surface: l.sirio_frame_surface,
        terminal_surface: l.sirio_terminal_surface,
        dialog_surface: l.sirio_dialog_surface,
        floating_surface: l.sirio_floating_surface,
        overlay: l.sirio_overlay,
        overlay_strong: l.sirio_overlay_strong,
        border_strong: s.sirio_border_strong,
        ring: s.sirio_ring,
        text_dim: l.sirio_text_dim,
        danger_muted: s.sirio_danger_muted,
        quantity: l.sirio_quantity,
        solid: l.sirio_solid,
        on_solid: l.sirio_on_solid,
        brand_coral: s.sirio_brand_coral,
        code_wash: s.sirio_code_wash,
        tree_guide: s.sirio_tree_guide,
        diff_add: s.sirio_diff_add,
        diff_add_bg: s.sirio_diff_add_bg,
        diff_del: s.sirio_diff_del,
        diff_del_bg: s.sirio_diff_del_bg,
    };
    (palette, sirio)
}
